code.css:
.cb__l{display:block;margin-bottom:6px;font:600 14px system-ui,sans-serif}
.cb{position:relative;width:260px;font:15px system-ui,sans-serif}
.cb input{width:100%;min-height:44px;padding:8px 12px;border:1px solid #8a8a8a;border-radius:8px;font:inherit}
.cb__list{position:absolute;inset:48px 0 auto;margin:0;padding:4px;list-style:none;background:#fff;border:1px solid #8a8a8a;border-radius:8px;box-shadow:0 14px 34px -10px rgba(0,0,0,.3)}
.cb__list li{padding:10px;border-radius:6px}
.cb__list li[aria-selected=true]{background:#f0f0f0;font-weight:600}
